def rank_risks(risks):
    out = []
    for r in risks:
        l, i = r['likelihood'], r['impact']
        if not (1 <= l <= 5 and 1 <= i <= 5):
            raise ValueError(f"bad rating for {r['area']}")
        score = l * i
        level = 'high' if score >= 15 else 'medium' if score >= 8 else 'low'
        out.append((r['area'], score, level))
    return sorted(out, key=lambda t: (-t[1], t[0]))

